/** theme.role_not_table: {file}: {role} needs a table of settings, like {role} = {{ fg = … }} */
export function themeRoleNotTable(file: unknown, role: unknown): string { return `${file}: ${role} needs a table of settings, like ${role} = { fg = … }`; }

/** theme.show_merged: {name}, with the themes it extends and the color names every theme has
merged in. It looks the same saved as a file of its own. A role
inherits from the one before its last dot. */
export function themeShowMerged(name: unknown): string { return `${name}, with the themes it extends and the color names every theme has
merged in. It looks the same saved as a file of its own. A role
inherits from the one before its last dot.`; }

/** theme.swatch_sample: Sample */
export function themeSwatchSample(): string { return `Sample`; }

/** theme.tag_entry: tag {name} */
export function themeTagEntry(name: unknown): string { return `tag ${name}`; }

/** theme.tag_not_table: {file}: tag {tag:%q} needs a table of settings, like {{ fg = … }} */
export function themeTagNotTable(file: unknown, tag: unknown): string { return `${file}: tag ${q(tag)} needs a table of settings, like { fg = … }`; }

/** theme.unknown_field: {file}: {role}: unknown setting {field:%q} */
export function themeUnknownField(file: unknown, role: unknown, field: unknown): string { return `${file}: ${role}: unknown setting ${q(field)}`; }

/** theme.unknown_key: {file}: unknown key {key:%q} (a theme has extends, palette, ui and tags) */
export function themeUnknownKey(file: unknown, key: unknown): string { return `${file}: unknown key ${q(key)} (a theme has extends, palette, ui and tags)`; }

/** theme.unknown_role: {file}: unknown role {role:%q} */
export function themeUnknownRole(file: unknown, role: unknown): string { return `${file}: unknown role ${q(role)}`; }

